import React, { useState, useEffect } from 'react';
import { db } from '../data/db';

export const FormularioPreventa = () => {
  const [formData, setFormData] = useState({ cliente: '', producto: '', cantidad: 1 });
  const [mensaje, setMensaje] = useState('');
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Monitor de conexión
  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  const guardarLocal = async (e) => {
    e.preventDefault();
    try {
      await db.pedidos.add({
        ...formData,
        sincronizado: 0,
        fecha: new Date().toISOString()
      });
      setMensaje("✔ Pedido guardado localmente");
      setFormData({ cliente: '', producto: '', cantidad: 1 });
      setTimeout(() => setMensaje(''), 3000);
    } catch (error) {
      console.error("Error al guardar:", error);
    }
  };

  return (
    <div style={{ padding: '20px', maxWidth: '400px', margin: 'auto' }}>
      {/* Indicador de estado */}
      <div style={{ 
        padding: '5px', 
        borderRadius: '5px', 
        backgroundColor: isOnline ? '#d4edda' : '#f8d7da', 
        color: isOnline ? '#155724' : '#721c24',
        textAlign: 'center',
        marginBottom: '15px',
        fontSize: '12px'
      }}>
        {isOnline ? '🟢 Conectado - Sincronización lista' : '🔴 Modo Offline - Guardando en dispositivo'}
      </div>

      <h2>Nuevo Pedido</h2>
      <form onSubmit={guardarLocal} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        <input 
          style={{ padding: '10px', fontSize: '16px' }} // Fuente grande para móviles
          type="text" placeholder="Cliente" value={formData.cliente} 
          onChange={e => setFormData({...formData, cliente: e.target.value})} required />
        <input 
          style={{ padding: '10px', fontSize: '16px' }}
          type="text" placeholder="Producto" value={formData.producto}
          onChange={e => setFormData({...formData, producto: e.target.value})} required />
        <input 
          style={{ padding: '10px', fontSize: '16px' }}
          type="number" value={formData.cantidad}
          onChange={e => setFormData({...formData, cantidad: e.target.value})} min="1" />
        <button type="submit" style={{ background: '#28a745', color: 'white', border: 'none', padding: '15px', fontSize: '16px', fontWeight: 'bold' }}>
          GUARDAR PEDIDO
        </button>
      </form>
      {mensaje && <p style={{ color: 'green', marginTop: '10px', textAlign: 'center' }}>{mensaje}</p>}
    </div>
  );
};
